"use client";

import "./table.css";

import type React from "react";

import { cn } from "tailwind-variants";

import { TableContext, useTableContext } from "./table.context";
import { tableVariants, type TableVariants } from "./table.variants";

export type TableProps = TableVariants & React.HTMLAttributes<HTMLTableElement>;

export const TableRoot = ({ children, className, ...props }: TableProps) => {
  const slots = tableVariants();

  return (
    <TableContext.Provider value={{ slots }}>
      <div className={slots.root()}>
        <table className={cn(slots.table(), className)} {...props}>
          {children}
        </table>
      </div>
    </TableContext.Provider>
  );
};

export type TableHeaderProps = React.HTMLAttributes<HTMLTableSectionElement>;

export const TableHeader = ({ className, ...props }: TableHeaderProps) => {
  const { slots } = useTableContext();
  return <thead className={cn(slots.header(), className)} {...props} />;
};

export type TableBodyProps = React.HTMLAttributes<HTMLTableSectionElement>;

export const TableBody = ({ className, ...props }: TableBodyProps) => {
  const { slots } = useTableContext();
  return <tbody className={cn(slots.body(), className)} {...props} />;
};

export type TableFooterProps = React.HTMLAttributes<HTMLTableSectionElement>;

export const TableFooter = ({ className, ...props }: TableFooterProps) => {
  const { slots } = useTableContext();
  return <tfoot className={cn(slots.footer(), className)} {...props} />;
};

export type TableRowProps = React.HTMLAttributes<HTMLTableRowElement>;

export const TableRow = ({ className, ...props }: TableRowProps) => {
  const { slots } = useTableContext();
  return <tr className={cn(slots.row(), className)} {...props} />;
};

export type TableHeadProps = React.ThHTMLAttributes<HTMLTableCellElement>;

export const TableHead = ({ className, ...props }: TableHeadProps) => {
  const { slots } = useTableContext();
  return <th className={cn(slots.head(), className)} {...props} />;
};

export type TableCellProps = React.TdHTMLAttributes<HTMLTableCellElement>;

export const TableCell = ({ className, ...props }: TableCellProps) => {
  const { slots } = useTableContext();
  return <td className={cn(slots.cell(), className)} {...props} />;
};

export type TableCaptionProps = React.HTMLAttributes<HTMLTableCaptionElement>;

export const TableCaption = ({ className, ...props }: TableCaptionProps) => {
  const { slots } = useTableContext();
  return <caption className={cn(slots.caption(), className)} {...props} />;
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const tableVariants = tv({
  slots: {
    root: "table-container",
    table: "table",
    header: "table__header",
    body: "table__body",
    footer: "table__footer",
    row: "table__row",
    head: "table__head",
    cell: "table__cell",
    caption: "table__caption",
  },
});

export type TableVariants = VariantProps<typeof tableVariants>;

"use client";

import { createContext, useContext } from "react";

import { tableVariants } from "./table.variants";

export type TableContext = {
  slots: ReturnType<typeof tableVariants>;
};

export const TableContext = createContext<TableContext | null>(null);

export const useTableContext = () => {
  const context = useContext(TableContext);
  return context ?? { slots: tableVariants() };
};

.table-container {
  @apply relative w-full overflow-auto;
}

.table {
  @apply w-full caption-bottom text-sm;
}

.table__header {
  @apply border-b border-border;
}

.table__body {
  @apply [&_tr:last-child]:border-0;
}

.table__footer {
  @apply border-t border-border bg-muted/50 font-medium [&>tr]:last:border-b-0;
}

.table__row {
  @apply border-b border-border transition-colors hover:bg-muted/50 data-[state=selected]:bg-muted;
}

.table__head {
  @apply h-10 px-4 text-left align-middle font-medium text-muted-foreground [&:has([role=checkbox])]:pr-0;
}

.table__cell {
  @apply p-4 align-middle [&:has([role=checkbox])]:pr-0;
}

.table__caption {
  @apply mt-4 text-sm text-muted-foreground;
}

import {
  TableBody,
  TableCaption,
  TableCell,
  TableFooter,
  TableHead,
  TableHeader,
  TableRoot,
  TableRow,
} from "./table";

export const Table = {
  Body: TableBody,
  Caption: TableCaption,
  Cell: TableCell,
  Footer: TableFooter,
  Head: TableHead,
  Header: TableHeader,
  Root: TableRoot,
  Row: TableRow,
};

export {
  TableBody,
  TableCaption,
  TableCell,
  TableFooter,
  TableHead,
  TableHeader,
  TableRoot,
  TableRow,
};

export type {
  TableBodyProps,
  TableCaptionProps,
  TableCellProps,
  TableFooterProps,
  TableHeadProps,
  TableHeaderProps,
  TableProps,
  TableRowProps,
} from "./table";
export { TableContext, useTableContext } from "./table.context";
export { type TableVariants, tableVariants } from "./table.variants";
